using System;
using System.Collections.Generic;
using Astrea.GameStates;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

public class GameStateManager : ReferenceSingleton<GameStateManager>
{
	[Header("State Map")]
	[SerializeField]
	private ChooseActionState chooseActionState;

	[SerializeField]
	private ActionsQueueState actionsQueueState;

	[SerializeField]
	private InitializeBattleState initializeBattleState;

	[SerializeField]
	private StartPlayerTurnState startPlayerTurnState;

	[SerializeField]
	private GameState diceTargetCastState;

	[SerializeField]
	private GameState chooseDiceState;

	[SerializeField]
	private GameState chooseDiceOnPoolState;

	[SerializeField]
	private GameState choosePlayerDiceState;

	[SerializeField]
	private GameState chooseEnemyDiceState;

	[SerializeField]
	private EndPlayerTurnState endPlayerTurnState;

	[SerializeField]
	private GameState precisionActionState;

	[SerializeField]
	private EndOfAllTurnState endOfAllTurnState;

	[SerializeField]
	private GameState deathState;

	[SerializeField]
	private GameState noInteractionState;

	[SerializeField]
	private ChooseActionStateInspectOnly chooseActionStateInspectOnly;

	[SerializeField]
	private List<GameState> noEnterChooseActionStates;

	[Header("Non Battle State Map")]
	[SerializeField]
	private EndOfBattleState endOfBattleState;

	[SerializeField]
	private GameState playerRewardState;

	[SerializeField]
	private MapState mapState;

	[SerializeField]
	private GameState playerUnlockablesState;

	[Header("Enemy State Map")]
	[SerializeField]
	private CorruptPlayerState corruptPlayerState;

	[Header("Run Modifiers State")]
	[SerializeField]
	private GameState sealedPoolRunModifierChoosingDiceState;

	[Header("Assets")]
	[SerializeField]
	private MapHandler mapHandler;

	[SerializeField]
	private GameController gameController;

	[Header("Tutorial")]
	[SerializeField]
	private GameObject sothisTutorialHandlerPrefab;

	private bool sothisTutorialActive;

	private SothisTutorialHandler sothisTutorialHandler;

	[Header("Locks")]
	public bool EndOfBattleStateQueueLock;

	[Header("Always Active Actions")]
	[SerializeField]
	private Astrea.GameStates.Action[] alwaysActiveActions;

	[SerializeField]
	private Astrea.GameStates.Action[] alwaysActiveDuringBattleSceneButOnPauseMenuActions;

	[SerializeField]
	private OnMouseRightClickPreviewDice onMouseRightClickPreviewDice;

	[Header("Debug")]
	[SerializeField]
	private bool verbose;

	[SerializeField]
	private GameState debugState;

	[Header("Runtime")]
	[SerializeField]
	private GameState currentState;

	[SerializeField]
	private GameState previouslyGameState;

	[ShowNonSerializedField]
	private bool disableCurrentStateInput;

	[ShowNonSerializedField]
	private bool endOfBattleStateAlreadyCalled;

	private bool runEnded;

	[ShowNonSerializedField]
	private bool loading = true;

	public ChooseActionState ChooseActionState => chooseActionState;

	public ActionsQueueState ActionsQueueState => actionsQueueState;

	public InitializeBattleState InitializeBattleState => initializeBattleState;

	public StartPlayerTurnState StartPlayerTurnState => startPlayerTurnState;

	public GameState DiceTargetCastState => diceTargetCastState;

	public GameState ChooseDiceState => chooseDiceState;

	public GameState ChooseDiceOnPoolState => chooseDiceOnPoolState;

	public GameState ChoosePlayerDiceState => choosePlayerDiceState;

	public GameState ChooseEnemyDiceState => chooseEnemyDiceState;

	public EndPlayerTurnState EndPlayerTurnState => endPlayerTurnState;

	public GameState PrecisionActionState => precisionActionState;

	public EndOfAllTurnState EndOfAllTurnState => endOfAllTurnState;

	public GameState DeathState => deathState;

	public GameState NoInteractionState => noInteractionState;

	public GameState ChooseActionStateInspectOnly => chooseActionStateInspectOnly;

	public List<GameState> NoEnterChooseActionStates => noEnterChooseActionStates;

	public EndOfBattleState EndOfBattleState => endOfBattleState;

	public GameState PlayerRewardState => playerRewardState;

	public GameState MapState => mapState;

	public GameState PlayerUnlockablesState => playerUnlockablesState;

	public CorruptPlayerState CorruptPlayerState => corruptPlayerState;

	public GameState SealedPoolRunModifierChoosingDiceState => sealedPoolRunModifierChoosingDiceState;

	public GameState CurrentState => currentState;

	public GameState PreviouslyGameState => previouslyGameState;

	public bool IsOnChooseActionState
	{
		get
		{
			if (!(currentState == chooseActionState))
			{
				return currentState == chooseActionStateInspectOnly;
			}
			return true;
		}
	}

	public bool IsOnDeathState => currentState == deathState;

	public bool EndOfBattleStateAlreadyCalled => endOfBattleStateAlreadyCalled;

	public bool IsOnPlayerUnlockablesState => currentState == playerUnlockablesState;

	private List<GameState> nonBattleState => new List<GameState> { endOfBattleState, playerRewardState, mapState };

	private List<GameState> nonBattleStateAndUnlockablesState => new List<GameState> { endOfBattleState, playerRewardState, mapState, playerUnlockablesState };

	public void SetDisableCurrentStateInput(bool value)
	{
		disableCurrentStateInput = value;
	}

	public void SetLoading(bool value)
	{
		loading = value;
	}

	public bool CurrentGameStateIsNonBattleState()
	{
		return nonBattleState.Contains(currentState);
	}

	public bool IsCurrentGameStateNonBattleStateAndUnlockablesStateOrEndOfBattleStateHasAlreadyBeingCalled()
	{
		if (!endOfBattleStateAlreadyCalled)
		{
			return nonBattleStateAndUnlockablesState.Contains(currentState);
		}
		return true;
	}

	public bool CurrentGameStateIsNonBattleStateAndUnlockablesState()
	{
		return nonBattleStateAndUnlockablesState.Contains(currentState);
	}

	public void ResetGameStateSOs()
	{
		EndOfBattleStateQueueLock = false;
		endOfBattleStateAlreadyCalled = false;
		corruptPlayerState.OnReset();
		startPlayerTurnState.OnReset();
		endPlayerTurnState.OnReset();
		actionsQueueState.OnReset();
		chooseActionState.OnReset();
		endOfBattleState.OnReset();
		endOfAllTurnState.OnReset();
		onMouseRightClickPreviewDice.OnReset();
	}

	public void InitializeBattleResetGameStateSOs()
	{
		ResetGameStateSOs();
	}

	public void InitializeBattle()
	{
		if (!sothisTutorialActive)
		{
			SetState(initializeBattleState);
			return;
		}
		sothisTutorialHandler.PlayHighlightAnimationAndShowTooltip();
		sothisTutorialActive = false;
	}

	public void CheckSothisTutorial()
	{
		if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterName == "Sothis" && ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterProgression.CharacterXP == 0 && mapHandler.CurrentAreaIndex == 0 && mapHandler.CurrentAreaLevelIndex == 0)
		{
			sothisTutorialActive = true;
			SetNoInteractionState();
			sothisTutorialHandler = UnityEngine.Object.Instantiate(sothisTutorialHandlerPrefab).GetComponent<SothisTutorialHandler>();
		}
	}

	private void Update()
	{
		if (!runEnded && !ReferenceSingleton<InputManager>.Instance.IsPaused && !loading)
		{
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunStats.Execute();
		}
		if (!disableCurrentStateInput && !ReferenceSingleton<InputManager>.Instance.IsPaused)
		{
			currentState.Execute(Time.deltaTime);
		}
		for (int i = 0; i < alwaysActiveActions.Length; i++)
		{
			alwaysActiveActions[i].Execute(Time.deltaTime);
		}
		if (!ReferenceSingleton<InputManager>.Instance.IsPaused && !ReferenceSingleton<InputManager>.Instance.IsJoystickBeingUsedDynamicInput())
		{
			for (int j = 0; j < alwaysActiveDuringBattleSceneButOnPauseMenuActions.Length; j++)
			{
				alwaysActiveDuringBattleSceneButOnPauseMenuActions[j].Execute(Time.deltaTime);
			}
		}
	}

	public void SetState(GameState gameState, bool skipOnStart = false, bool skipOnEnd = false)
	{
		if (currentState == deathState && gameState != playerUnlockablesState)
		{
			$"GameStateManager: {gameState.name} Trying to enter another state when on death state".DebugLogIfVerbose(verbose);
			return;
		}
		if (currentState == gameState)
		{
			$"GameStateManager: {gameState.name} Trying to enter same state again".DebugLogIfVerbose(verbose);
			return;
		}
		if (gameState == endOfBattleState && EndOfBattleStateQueueLock)
		{
			$"GameStateManager: {gameState.name} Trying to enter EndOfBattleState with EndOfBattleStateQueueLock On".DebugLogIfVerbose(verbose);
			return;
		}
		if (currentState != null)
		{
			$"============================== ON END STATE: {currentState.name}  ==================================".DebugLogIfVerbose(verbose);
			if (!skipOnEnd)
			{
				currentState.OnEndState();
			}
		}
		previouslyGameState = currentState;
		if (gameState == previouslyGameState)
		{
			"GameStateManager: Trying to change to previously state".DebugLogIfVerbose(verbose);
			if (previouslyGameState != null)
			{
				previouslyGameState = null;
				currentState = gameState;
				$"============================== ON START PREVIOUSLY STATE: {currentState.name}  ==================================".DebugLogIfVerbose(verbose);
				if (!skipOnStart)
				{
					currentState.OnStartState();
				}
			}
			else
			{
				"GameStateManager: No previously state, go to default state ChooseActionState".DebugLogIfVerbose(verbose);
				SetState(chooseActionState);
			}
			return;
		}
		"GameStateManager: Trying to change to new state".DebugLogIfVerbose(verbose);
		if (gameState == null)
		{
			"GameStateManager: State null".DebugLogIfVerbose(verbose);
			currentState = gameState;
			return;
		}
		currentState = gameState;
		$"============================== ON START STATE: {currentState.name}  ==================================".DebugLogIfVerbose(verbose);
		if (!skipOnStart)
		{
			currentState.OnStartState();
		}
	}

	public void TryEnterNoInteractionState()
	{
		TurnManager turnManager = ReferenceSingleton<TurnManager>.Instance;
		if (turnManager.CurrentTurn == turnManager.PlayerTurn && currentState != actionsQueueState && currentState != initializeBattleState && currentState != startPlayerTurnState && currentState != endPlayerTurnState && currentState != mapState && currentState != precisionActionState && currentState != null)
		{
			SetNoInteractionState();
		}
	}

	public void TryEnterChooseActionState(WaitForFramesType waitForFramesType = WaitForFramesType.ThreeFrames)
	{
		System.Action tryEnterChooseActionStateAction = delegate
		{
			if (ReferenceSingleton<TurnManager>.Instance.CurrentTurn == ReferenceSingleton<TurnManager>.Instance.PlayerTurn && !ReferenceSingleton<DiceRollingHandler>.Instance.IsDiceRolling && currentState != actionsQueueState && currentState != initializeBattleState && currentState != startPlayerTurnState && currentState != diceTargetCastState && currentState != chooseDiceState && currentState != chooseDiceOnPoolState && currentState != choosePlayerDiceState && currentState != chooseEnemyDiceState && currentState != endPlayerTurnState && currentState != precisionActionState && currentState != deathState && currentState != endOfBattleState && currentState != corruptPlayerState && currentState != playerRewardState && currentState != mapState && currentState != null)
			{
				SetChooseActionState();
			}
		};
		int num = 0;
		switch (waitForFramesType)
		{
		case WaitForFramesType.ThreeFrames:
			num = 3;
			break;
		case WaitForFramesType.WaitToUpdateCorruptionFrames:
			num = ReferenceSingleton<BattleHandler>.Instance.FramesToWaitToUpdateCorruption + 1;
			break;
		}
		if (num == 0)
		{
			tryEnterChooseActionStateAction();
			return;
		}
		InvokeAlternatives.InvokeAfterMultipleFrames(this, num, delegate
		{
			tryEnterChooseActionStateAction();
		});
	}

	public void SetChooseActionState()
	{
		if (!ReferenceSingleton<DiceRollingHandler>.Instance.IsDiceRolling)
		{
			SetState(chooseActionState);
		}
	}

	public void SetNoInteractionState()
	{
		SetState(noInteractionState);
	}

	public void SetActionsQueueState()
	{
		SetState(actionsQueueState);
	}

	public void SetPlayerRewardStateState()
	{
		SetState(playerRewardState);
	}

	public void SetEndOfBattleStateWithQueueLockFalse()
	{
		ReferenceSingleton<GameStateManager>.Instance.EndOfBattleStateQueueLock = false;
		SetState(endOfBattleState);
	}

	public void TryEnterEndOfBattleStateFirstTimeOnly()
	{
		if (!IsCurrentGameStateNonBattleStateAndUnlockablesStateOrEndOfBattleStateHasAlreadyBeingCalled())
		{
			endOfBattleStateAlreadyCalled = true;
			EndOfBattleStateQueueLock = false;
			SetState(EndOfBattleState);
		}
		else
		{
			Debug.Log("--GameStateManager: Trying to enter EndOfBattleState with endOfBattleStateAlreadyCalled!!!--");
		}
	}

	public void TryEnterEndPlayerTurnStateIfNotEndOfBattleStateAlreadyCalled(bool onActionsOnQueueEndedRefEvent = false)
	{
		if (!endOfBattleStateAlreadyCalled)
		{
			actionsQueueState.OnActionsOnQueueEndedRef.Raise();
			SetState(endPlayerTurnState);
		}
		else
		{
			Debug.Log("--GameStateManager: Trying to enter EndPlayerTurnState with endOfBattleStateAlreadyCalled!!!--");
		}
	}

	public void OnBossDefeated()
	{
		int num = ((!gameController.IsDemo) ? ((!ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentRunAstreasHeartEnabled) ? 2 : 3) : 0);
		if (mapHandler.CurrentAreaIndex == num)
		{
			runEnded = true;
		}
	}
}
